insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('gasprocessing', 'intermediate', 'module', 'm01-a-contactor-is-a-staged-device', 1, 'A theoretical stage in this module is fixed by one condition. Which condition is it?', '["The gas and the liquid stay in contact for a stated time before they are allowed to separate again.", "The gas leaving the stage already meets the column''s outlet spec.", "The gas and the liquid leave the stage in equilibrium with each other.", "The liquid leaving the stage has picked up as much solute as its own rich limit allows it to carry."]'::jsonb, 2, 'Height, tray spacing, contact time and mechanical design enter nowhere in that definition. A stage is a unit of separation difficulty, and it is the only absorber model this engine carries.'),
  ('gasprocessing', 'intermediate', 'module', 'm01-a-contactor-is-a-staged-device', 2, 'Which three quantities does the Kremser relation tie together?', '["The absorption factor, the number of theoretical stages, and the fraction of the solute removed.", "The gas rate in MMscfd, the number of theoretical stages, and the fraction of the solute removed.", "The liquid molar rate, the gas molar rate, and the equilibrium ratio of the solute between the phases.", "The number of theoretical stages, the tray efficiency of the service, and the fraction of the solute removed."]'::jsonb, 0, 'Give it any two and it gives the third. That shape is why one piece of arithmetic answers both what a column of a given size removes and how large a column a spec demands.'),
  ('gasprocessing', 'intermediate', 'module', 'm01-a-contactor-is-a-staged-device', 3, 'The absorption factor is written A = L / (V K). What do the three symbols stand for?', '["L is the solvent rate in gpm, V is the gas rate in MMscfd, and K is the Souders-Brown K value in ft per s.", "L is the lean loading, V is the loading swing, and K is the equilibrium ratio at the column''s conditions.", "L is the solvent molar rate, V is the gas molar rate, and K is the number of theoretical stages in the column.", "L is the solvent molar rate down the column, V is the gas molar rate up it, and K is the equilibrium ratio of the solute between the two phases."]'::jsonb, 3, 'The factor is dimensionless and it is the one number in the relation that carries the equilibrium. None of L, V or K is an argument of any export in this module.'),
  ('gasprocessing', 'intermediate', 'module', 'm01-a-contactor-is-a-staged-device', 4, 'Where does the absorption factor come from when this module is asked what a column removes?', '["It is built from the amine circulation and the acid gas rate that the sweetening call returns for the same stream, which is how the two halves of the module share one column.", "It arrives as a typed input taken from equilibrium data, because none of the three quantities behind it is an argument of any export here.", "It is formed from the gas gravity and the column pressure by the correlation that also gives the compressibility.", "It is read from the property row of the amine named in the call, beside that amine''s strength and rich limit."]'::jsonb, 1, 'That seam is why every table in this section is indexed by the factor rather than by a rate. A removal figure is only as good as the factor somebody typed above it.'),
  ('gasprocessing', 'intermediate', 'module', 'm01-a-contactor-is-a-staged-device', 5, 'On the OBIAFU absorber the absorption factor is 1.600000 and the column carries 6.000000 stages. What does the relation return?', '["A removal of 0.976783371, which is a fraction of the solute arriving.", "A removal of 0.922576074, because 1.600000 is rounded down to the column at 1.2.", "A removal of 0.992125984, because 1.600000 is read on the surface column nearest above it.", "A removal of 0.976783371 mol percent of the inlet gas."]'::jsonb, 0, 'The figure is a fraction of the solute present, so it says nothing about the rate, the pressure or the vessel. It is the column''s efficiency at the duty it was given.'),
  ('gasprocessing', 'intermediate', 'module', 'm01-a-contactor-is-a-staged-device', 6, 'Why does this course tell a reader to work down the Kremser surface by column rather than across it by row?', '["A row mixes two units, because the stage entries are counts and the factor entries are dimensionless.", "A row is only valid above an absorption factor of one, and four of the seven columns fall below it.", "A column of the surface is one absorber being made taller, and a row is a set of columns that do not exist together.", "A column holds the factor steady, which is the only way to reach the 200 stage entries the surface extends to."]'::jsonb, 2, 'Nobody builds one absorber and then walks its solvent circulation across a whole row. Above an absorption factor of one every column climbs towards total removal as stages are added.'),
  ('gasprocessing', 'intermediate', 'module', 'm01-a-contactor-is-a-staged-device', 7, 'At an absorption factor of exactly 1 the closed form cannot be evaluated. What does the engine return instead?', '["A refusal naming the factor, because the relation is indeterminate there and no removal exists.", "The stages over the stages plus one, which at 4 stages gives 0.800000000 and at 12 gives 0.923076923.", "The closed form evaluated a billionth above the factor it was handed, which is 0.923076923 at 12 stages.", "The absorption factor itself, since at unity the ceiling and the removal have met."]'::jsonb, 1, 'Numerator and denominator both vanish at that factor, and the stages over the stages plus one is the limit there. One stage gives 0.500000000 on that column of the surface.'),
  ('gasprocessing', 'intermediate', 'module', 'm01-a-contactor-is-a-staged-device', 8, 'Two numbers go into the Kremser relation and one comes out. What is unusual about that in this package?', '["Most of what the Facilities engines answer arrives as a surface sampled at seven points, which is what the table below it is.", "Most of what the Facilities engines answer is solved iteratively, and this relation is the only closed form among them.", "Most of what the Facilities engines answer carries a warning band, and this relation carries none at any absorption factor.", "Most of what the Facilities engines answer arrives as a chain of steps, each with its own input and its own unit."]'::jsonb, 3, 'Here the entire behaviour of a staged absorber sits in the shape of one expression, and the surface is that shape sampled. The sweetening chain in the next module is the other kind, five steps with a property on each.'),
  ('gasprocessing', 'intermediate', 'module', 'm01-a-contactor-is-a-staged-device', 9, 'The published cases behind the Kremser relation are solved a second way. Which way?', '["A brute force stage cascade solved as a linear system, which reaches the same numbers by a genuinely different road.", "The same closed form evaluated in higher precision, so the check is on the rounding rather than on the algebra.", "The inverse relation run backwards from the removal, so each case checks that the two directions agree.", "A published correlation chart digitised at the five factors the golden carries."]'::jsonb, 0, 'A check that restates the relation it is checking can only confirm that the typing is consistent. This golden never writes the relation down, and the five ratios of engine over golden come back at 1.000000000000.'),
  ('gasprocessing', 'intermediate', 'module', 'm01-a-contactor-is-a-staged-device', 10, 'Why does the Kremser golden carry a case at an absorption factor of 1.000000 with 5 stages?', '["Because 5 stages is the count at which the general form and the branch at unity are known to cross over and agree.", "Because the cascade golden can only be solved as a linear system when the factor is one.", "Because the engine takes a separate branch at that factor, so the branch needs a published case of its own.", "Because it is the only case in the set whose removal, 0.833333333333, repeats to twelve figures."]'::jsonb, 2, 'A golden made entirely of general-form cases would pass whatever the branch did. The case returns 0.833333333333 on both sides and its ratio is 1.000000000000.'),
  ('gasprocessing', 'intermediate', 'module', 'm01-a-contactor-is-a-staged-device', 11, 'The relation is inverted to give the stages a spec demands. Which form does the engine use away from unity?', '["N = f / (1 - f), which is the general form and reduces to the closed form at unity.", "N = log( (1 - f) / (A - f) ) / log(A) + 1, with the ratio inverted.", "N = (A - f) / (A - 1), taken directly from the forward relation.", "N = log( (A - f) / (1 - f) ) / log(A) - 1."]'::jsonb, 3, 'Reading A^(N+1) = (A - f) / (1 - f) rather than the solved line is what makes the ceiling fall out: the left side is positive for any real N, so with f below one the factor has to exceed the removal. The f over 1 minus f form is the branch at unity.'),
  ('gasprocessing', 'intermediate', 'module', 'm01-a-contactor-is-a-staged-device', 12, 'A contract asks for a removal of 0.900000. What stage counts come back at absorption factors of 1.200000 and 1.600000?', '["3.140202390 and 5.025685103, the better supplied column needing the taller answer.", "5.025685103 and 3.140202390.", "5.025685103 and 7.746472598, which is the same spec read on the two supplied factors.", "9.000000000 and 5.658211483, the two entries the inverse carries at that removal."]'::jsonb, 1, 'Both are answers to the same contractual requirement, and the difference between them is a decision about the solvent side taken before the relation was ever called.'),
  ('gasprocessing', 'intermediate', 'module', 'm01-a-contactor-is-a-staged-device', 13, 'Each row of the inverse table carries a final column putting the stage count straight back through the forward relation. What does that column establish?', '["That the two directions are inverses of one another rather than two pieces of arithmetic that happen to sit near each other.", "That the stage counts are converged, because the engine iterates towards them and stops when the removal stops moving.", "That the removals asked for are reachable at those factors, which is what the ceiling would otherwise have to be consulted for.", "That rounding the fractional stage count to a whole number leaves the removal within the precision this course prints."]'::jsonb, 0, 'It returns the removal that was asked for on every row. That is the cheapest possible test of a two-way relation, and most published correlations cannot pass it.'),
  ('gasprocessing', 'intermediate', 'module', 'm01-a-contactor-is-a-staged-device', 14, 'The inverse returns stage counts such as 3.140202390 and 7.746472598. How should a fractional count be read?', '["As a figure to round up at once, since a column is built with whole trays and the next whole number up is the safe side to order.", "As a sign that the absorption factor sits too close to unity for the inverse to resolve a whole count.", "As an exact answer to a question about separation difficulty, with the rounding left to whoever converts stages into trays.", "As the theoretical count already multiplied by a tray efficiency, which is what puts a fraction on the end of a count like that."]'::jsonb, 2, 'A theoretical stage is a unit of separation difficulty, so a spec can perfectly well ask for a fraction of one. The conversion into real trays is not in this module.'),
  ('gasprocessing', 'intermediate', 'module', 'm01-a-contactor-is-a-staged-device', 15, 'What separates the rating direction of the relation from the design direction?', '["The rating direction takes the absorption factor as an input and the design direction computes one from the spec.", "The rating direction belongs to a column that exists and returns a removal, and the design direction belongs to a column that does not exist yet and returns a stage count.", "The rating direction is checked against the golden and the design direction is checked against the ceiling.", "The rating direction holds at and below an absorption factor of one, and the design direction only above it."]'::jsonb, 1, 'One asks whether next quarter''s gas still meets the spec on the stages already bought. The other asks how large a problem is about to be handed to a vendor.'),
  ('gasprocessing', 'intermediate', 'module', 'm02-what-the-absorption-factor-can-buy', 1, 'Stages and the absorption factor are bought in different currencies. Which pairing is right?', '["Stages are solvent and regeneration; the absorption factor is steel, because a taller vessel is what raises it.", "Stages are steel and height; the absorption factor is solvent, with the pumping and regeneration that come with it.", "Stages are capital and the absorption factor is capital too, since both are fixed once the column is ordered.", "Stages are set by the gas rate and the absorption factor by the spec, so neither is a purchase a project makes."]'::jsonb, 1, 'The relation itself prices nothing. There is no capital cost of a tray in it and no regeneration duty attached to a higher factor, and putting the two halves together is the work.'),
  ('gasprocessing', 'intermediate', 'module', 'm02-what-the-absorption-factor-can-buy', 2, 'What is the ceiling on a column whose absorption factor sits below one?', '["Total removal, reached more slowly than above unity but reached in the end.", "The removal the relation gives at 12 stages, past which further stages return nothing at all on any factor below one.", "One minus the absorption factor, so a starved column at 0.800000 is held to 0.200000 however many stages it carries.", "The absorption factor itself, which the removal approaches as stages are added and never passes."]'::jsonb, 3, 'Stages only walk the answer towards the factor. At an absorption factor of 0.600000000000 the removal at 12 stages is 0.599476889 and at 200 stages it is 0.600000000.'),
  ('gasprocessing', 'intermediate', 'module', 'm02-what-the-absorption-factor-can-buy', 3, 'On the lower rows of the ceiling table the gap between the removal at 200 stages and the absorption factor is exactly 0.000000000000. Why?', '["The factor raised to the stage count has fallen below anything double precision can hold, so the relation collapses to the factor itself.", "Those factors divide the stage count exactly, so the general form terminates rather than approaching a limit.", "The engine substitutes the factor for the removal once it detects a starved column, which is what makes the gap vanish.", "The table rounds the gap to twelve decimals, and on those rows the true gap falls below the last place printed."]'::jsonb, 0, 'That is a statement about the arithmetic of a computer rather than about an absorber, and it is worth naming as such. Only near one does 200 stages fall measurably short.'),
  ('gasprocessing', 'intermediate', 'module', 'm02-what-the-absorption-factor-can-buy', 4, 'Why does the ceiling column carry no meaning on the row at an absorption factor of 1.200000000000?', '["The engine refuses to evaluate 200 stages above unity, so the entry is a placeholder.", "Above unity the removal and the factor are equal by construction, so the entry can only ever be zero.", "There is no ceiling above unity to measure against, so the entry becomes the distance from a removal that cannot exceed one to a factor that can.", "The row lies outside the range the surface is sampled over, so nothing on it can be compared with the rows above."]'::jsonb, 2, 'The entry there is -0.200000000000 and it goes more negative the larger the factor, which is arithmetic about a column of a table rather than physics about an absorber.'),
  ('gasprocessing', 'intermediate', 'module', 'm02-what-the-absorption-factor-can-buy', 5, 'At an absorption factor of 0.950000000000 the removal at 200 stages is 0.949998335. What does that row show that the rows below it cannot?', '["That the ceiling above 0.950000000000 is no longer the absorption factor but the removal at 200 stages.", "That the removal at 12 stages, 0.897258427, is already within a millionth of the ceiling.", "That the engine switches to the branch at unity once the factor is within a twentieth of it.", "That 200 stages genuinely falls short of the ceiling, by -0.000001665057, rather than landing on it."]'::jsonb, 3, 'On the lower factors the gap prints as exactly zero because of what double precision can hold. Approaching unity the shortfall becomes measurable.'),
  ('gasprocessing', 'intermediate', 'module', 'm02-what-the-absorption-factor-can-buy', 6, 'The ceiling table is read at 0.999999999000, 1.000000000000 and 1.000000001000. What do those three rows establish together?', '["That the ceiling moves discontinuously through unity, which is why the engine needs a separate branch there.", "That the branch the engine takes at unity is continuous with the general form either side of it, so it is a limit rather than a patch.", "That the relation cannot be evaluated within a billionth of unity, so all three rows are served by one branch.", "That an absorption factor typed to nine decimals is the finest the relation can distinguish."]'::jsonb, 1, 'All three report 0.923076923 at 12 stages and 0.995024876 at 200. A special case whose answer does not join up with the formula either side of it is the defect; a special case as such is not.'),
  ('gasprocessing', 'intermediate', 'module', 'm02-what-the-absorption-factor-can-buy', 7, 'Asked for the stage count that meets a removal of 0.900000 at an absorption factor of 0.800000, the engine declines. What does the message name?', '["The factor, the spec and the stage count at which the removal stops improving.", "The factor, the ceiling and the nearest reachable spec, so the contract can be renegotiated against it.", "The factor it was handed, the ceiling that factor implies, the spec asked for, and the remedy.", "The spec, the ceiling and the number of stages already bought on the column in question."]'::jsonb, 2, 'It reads: an absorption factor of 0.8 caps the removal at 0.8 however many stages are added, and the spec asks for 0.9: no stage count reaches it; raise circulation.'),
  ('gasprocessing', 'intermediate', 'module', 'm02-what-the-absorption-factor-can-buy', 8, 'That refusal names a remedy. Which one?', '["More solvent, which is what raises the absorption factor.", "More trays, on the ground that the ceiling is approached asymptotically.", "A looser spec, fixed by the solvent chosen.", "A lower gas rate, which the factor carries."]'::jsonb, 0, 'A stage count could never have carried that. The relation is indexed by the factor rather than by a rate, and the factor is the quantity that more solvent moves.'),
  ('gasprocessing', 'intermediate', 'module', 'm02-what-the-absorption-factor-can-buy', 9, 'What would a very large stage count have cost a reader, had the engine returned one instead of declining?', '["They would have rounded it down to the nearest whole tray and met the spec anyway.", "They would have priced a great many trays for a spec that height cannot buy.", "They would have lost the ceiling, which is the only figure the answer object carries.", "They would have read it as a warning rather than as an answer, since no column is built that tall."]'::jsonb, 1, 'Returning a huge stage count invites the wrong purchase. Returning the ceiling in place of the spec silently answers a question nobody asked, and that is the failure mode this programme has seen most often.'),
  ('gasprocessing', 'intermediate', 'module', 'm02-what-the-absorption-factor-can-buy', 10, 'The refusal cannot tell a reader one thing about the spec it was handed. Which?', '["Whether the spec is a fraction or a mole percent, since the relation accepts either.", "Whether the spec was asked of the right solute, which the factor would have to carry.", "Whether the spec lies above the ceiling, which is the comparison that produced the refusal.", "Whether the spec is negotiable."]'::jsonb, 3, 'A removal target may be a pipeline contract, a plant heat balance, or a round number somebody wrote into a specification years ago. The engine treats it as given.'),
  ('gasprocessing', 'intermediate', 'module', 'm02-what-the-absorption-factor-can-buy', 11, 'Which two things would this engine need before a theoretical stage count could be turned into a vessel height?', '["A rate-based absorber model and a stage efficiency, and it carries neither.", "A tray spacing and a mist extractor K value, both of which belong to the Separation and Slug Catching course.", "A liquid density and an allowed velocity, which the contactor sizing call already forms.", "A gas rate and an operating pressure."]'::jsonb, 0, 'A theoretical stage is a place where the gas and the liquid leave in equilibrium. That is the whole of the model, so the count is an answer about separation difficulty and no answer about steel.'),
  ('gasprocessing', 'intermediate', 'module', 'm02-what-the-absorption-factor-can-buy', 12, 'What does rounding a theoretical stage count up to the next whole number and calling it a tray count quietly assume?', '["That the absorption factor was typed on the conservative side of the equilibrium data.", "That the removal the spec asked for was itself rounded to the precision the engine prints.", "That a tray does the work of a full equilibrium stage.", "That the column will be packed rather than trayed, since packing has no discrete stages."]'::jsonb, 2, 'Rounding does happen eventually, because trays come in whole numbers. It happens after somebody who knows the tray efficiency of the service has made the conversion, and that conversion is not in this module.'),
  ('gasprocessing', 'intermediate', 'module', 'm02-what-the-absorption-factor-can-buy', 13, 'A column at an absorption factor of 3 with 3 stages reaches 0.975000000. Which other entries on the surface land near it?', '["A column at 1.2 with 12 stages reaches 0.975000000 as well, which is why the surface prints the pair.", "A column at 1.5 with 12 stages reaches 0.997417616 and a column at 2 with 8 stages reaches 0.998043053.", "A column at 0.8 with 12 stages reaches 0.788365257, the nearest entry the starved half of the surface carries.", "A column at 1 with 8 stages reaches 0.888888889, which is the closest any unity column comes."]'::jsonb, 1, 'Those are three different balances between capital and operating cost and the relation is indifferent to which is chosen. What it will not allow is rescuing a starved column with height.'),
  ('gasprocessing', 'intermediate', 'module', 'm02-what-the-absorption-factor-can-buy', 14, 'When does the distance between a theoretical stage and a real tray stop mattering?', '["When the absorption factor is at or below one, because neither stages nor trays reach past the ceiling.", "When the stage count comes back whole, because no conversion is then needed.", "When the column is packed rather than trayed, because a packed height is quoted in theoretical stages directly.", "When the removal asked for is below the absorption factor, because the spec is then met on a single stage and no count has to be converted."]'::jsonb, 0, 'Tray efficiency, packing, vendor experience and vessel height are all irrelevant at that point, because the constraint is on the solvent side.'),
  ('gasprocessing', 'intermediate', 'module', 'm02-what-the-absorption-factor-can-buy', 15, 'A starved column at an absorption factor of 0.600000000000 is read at 12 stages and again at 200. What happens between the two?', '["The removal moves from 0.599476889 to 0.788365257, so the stages go on paying all the way up.", "The removal moves from 0.540441176 to 0.600000000, which is most of the way to the ceiling.", "The removal moves from 0.599476889 to 0.600000000, which is the ceiling itself.", "The removal stops moving after 12 stages."]'::jsonb, 2, 'Adding trays to a starved column moves the answer closer to a ceiling it was always going to sit under. That is the single most useful fact in the staged half of this module.'),
  ('gasprocessing', 'intermediate', 'module', 'm03-acid-gas-is-removed-by-moles', 1, 'Where in the sweetening chain does a mole count first become a mass?', '["At the inlet, because a mole percent is a mass fraction.", "At the last step of the chain, where the solution is turned into gallons.", "At the gas rate, because a rate in MMscfd is a mass flow once the gravity is known.", "At the loading, because a loading is pounds on pounds."]'::jsonb, 1, 'The gas carries a mole percent, the spec says what may stay, the difference is picked up mole by mole, and the loading is moles of acid gas per mole of amine. Everything before the gallons is counted rather than weighed.'),
  ('gasprocessing', 'intermediate', 'module', 'm03-acid-gas-is-removed-by-moles', 2, 'UBIE arrives at 5.200000 mol percent CO2 and 1.400000 mol percent H2S and has to leave at 2.000000 and 0.000400. Which two of those four describe the gas?', '["The CO2 pair, 5.200000 and 2.000000, and the H2S pair is the contract.", "The larger figure on each gas, 5.200000 and 2.000000, since a spec is the smaller.", "The inlet pair, 5.200000 and 1.400000, and the other two are a contract.", "None of the four, because the engine derives all of them from the stream."]'::jsonb, 2, 'The engine treats all four as inputs and picks none of them. The two spec figures carry most of the cost of the unit, and neither is derived from anything physical in this module.'),
  ('gasprocessing', 'intermediate', 'module', 'm03-acid-gas-is-removed-by-moles', 3, 'What acid gas removal do the UBIE inlet and spec figures imply?', '["4.599600000 mol percent, the two differences added.", "3.200000 mol percent, the CO2 difference alone.", "1.400000 mol percent, the H2S at the inlet.", "2.000000 mol percent, the CO2 spec."]'::jsonb, 0, 'It is 5.200000 less 2.000000, plus 1.400000 less 0.000400. The two acid gases are added and carried as one figure from there on, and neither difference on its own is the duty.'),
  ('gasprocessing', 'intermediate', 'module', 'm03-acid-gas-is-removed-by-moles', 4, 'The two acid gases are added and carried as one figure. What does that assume?', '["That H2S is the gas the loading limit was measured on.", "That the spec pair may be averaged into one figure.", "That the two molecular weights are close enough to merge.", "That a mole of H2S and a mole of CO2 load onto the amine on equal terms."]'::jsonb, 3, 'Whether a particular solvent behaves that way is not a question this module asks. The decision sits at the first step and everything after it sees one number.'),
  ('gasprocessing', 'intermediate', 'module', 'm03-acid-gas-is-removed-by-moles', 5, 'At 88.000000 MMscfd, what does a removal of 4.599600000 mol percent put into the solution?', '["10666.2009 lbmol a day.", "4.599600000 lbmol a day.", "525.893013 lbmol a day.", "10666.2009 lb a day."]'::jsonb, 0, 'The route runs from the rate in standard cubic feet a day, through the fraction of those that are acid gas, into pound moles by way of the standard cubic feet in a pound mole. The gallons a minute are a separate answer further down the chain, and the pound mole is a count rather than a weight.'),
  ('gasprocessing', 'intermediate', 'module', 'm03-acid-gas-is-removed-by-moles', 6, 'The plant is turned down and the gas rate falls. Which figure does NOT move?', '["The pound moles of acid gas a day.", "The mole percent removed.", "The circulation in gpm.", "The regenerator duty in MMBtu an hour."]'::jsonb, 1, 'A mole percent is intensive and describes the gas. Change the inlet or the spec and it moves; change the rate and it does not. The pound moles a day move with both, and the gallons and the duty follow the pound moles.'),
  ('gasprocessing', 'intermediate', 'module', 'm03-acid-gas-is-removed-by-moles', 7, 'At what base does this module define a standard cubic foot?', '["459.670000 degR.", "The pressure and temperature of the contactor.", "It defines none at all.", "14.696000 psia and 519.670000 degR."]'::jsonb, 3, 'The standard cubic feet in a pound mole, 379.483571856287, are derived from the gas constant at that base rather than quoted from anywhere, so there is only one base in play and nothing to disagree with.'),
  ('gasprocessing', 'intermediate', 'module', 'm03-acid-gas-is-removed-by-moles', 8, 'What is the LEAN LOADING?', '["The weight percent of amine in the solution.", "The difference between the two ends of the loop.", "What a mole of amine still carries as it comes back from the regenerator.", "The lowest loading before a corrosion warning."]'::jsonb, 2, 'It is an input. On UBIE it is 0.050000 mol of acid gas per mol of amine, and the rich loading at the other end of the loop is 0.480000.'),
  ('gasprocessing', 'intermediate', 'module', 'm03-acid-gas-is-removed-by-moles', 9, 'The engine returns no loading swing under any name. How does a reader get one?', '["By reading it off the amine property table, which carries a customary swing on every row.", "By subtracting the lean loading from the rich, since the swing is a difference.", "By dividing the circulation by the acid gas rate, which is the step the swing sits in.", "By asking for it, since the engine forms one when a caller names the field."]'::jsonb, 1, 'The swing is what each mole of amine carries round the loop and it is what sets the circulation. It is still not a figure the engine hands back, so a reader forms it from the two loadings and carries it themselves.'),
  ('gasprocessing', 'intermediate', 'module', 'm03-acid-gas-is-removed-by-moles', 10, 'On UBIE the rich loading is 0.480000 and the lean loading is 0.050000. What is the LOADING SWING, and what does it do?', '["0.430000000 mol per mol, and it sets the circulation.", "0.050000 mol per mol, and it sets the circulation.", "0.430000000 mol per mol, and it is the ceiling corrosion sets.", "0.480000 mol per mol, and it is what the contactor delivers."]'::jsonb, 0, 'The rich loading is a ceiling that corrosion sets and the swing is a throughput the regenerator buys. The swing is a difference the reader forms from the two loadings, and the engine returns it under no name at all.'),
  ('gasprocessing', 'intermediate', 'module', 'm03-acid-gas-is-removed-by-moles', 11, 'The rich end is taken to 0.550000 on MDEA. What comes back?', '["452.267991 gpm and 21.708864 MMBtu an hour, and nothing else.", "A refusal naming the customary limit of 0.500000.", "452.267991 gpm and 21.708864 MMBtu an hour, with a warning.", "904.535983 gpm and 43.417727 MMBtu an hour, with a warning."]'::jsonb, 2, 'A loading above a customary limit is a decision somebody may have taken deliberately, so the engine answers and says so on that answer. The swing on that row is 0.500000000.'),
  ('gasprocessing', 'intermediate', 'module', 'm03-acid-gas-is-removed-by-moles', 12, 'A rich loading of 0.500000 in one table and a lean loading of 0.030000 in the other both report 502.519990 gpm and 24.120960 MMBtu an hour. Why?', '["Both rows sit on MDEA''s customary rich limit, which is what the circulation uses.", "The two tables are one sweep printed twice, read from each end of the loop.", "The engine holds the circulation steady on any row that carries no warning.", "Both rows carry a swing of 0.450000000, and the circulation follows the swing."]'::jsonb, 3, 'The engine is not tracking where the swing came from. Two different pieces of plant work, one in the contactor and one in the still, arrive in the balance as the same subtraction.'),
  ('gasprocessing', 'intermediate', 'module', 'm03-acid-gas-is-removed-by-moles', 13, 'Taking the lean loading from 0.120000 to 0.010000 moves the circulation from 628.149988 to 481.136161 gpm and the regenerator from 30.151199 to 23.094536 MMBtu an hour. What is that table honestly for?', '["It says what it costs to strip the solution to each of those lean loadings.", "It says how far the lean end goes before the rich end is flagged for corrosion.", "It says how much solution a given lean loading has to move.", "It says what a leaner lean saves, which is why both columns fall together."]'::jsonb, 2, 'The duty per gallon is a stated input, 800.000000 Btu on every gallon circulated, so the duty column is the circulation in other units. What it costs to reach a lean loading is a question for a rate-based still model, and the last column of that table, 0.048000000 MMBtu an hour per gpm, does not move down it.'),
  ('gasprocessing', 'intermediate', 'module', 'm03-acid-gas-is-removed-by-moles', 14, 'Which figure turns pound moles of acid gas a day into pound moles of amine a day?', '["The loading swing, 0.430000000 mol per mol.", "The molecular weight, 119.160000 for MDEA.", "The strength, 45.000000 weight percent.", "The solution density, 64.883034 lb per ft3."]'::jsonb, 0, 'It is the only step in that chain about the process rather than about the fluid. The molecular weight, the strength and the density come after it, and the minutes in a day, 1440.000000000, close the chain at 525.893013 gpm.'),
  ('gasprocessing', 'intermediate', 'module', 'm03-acid-gas-is-removed-by-moles', 15, 'On UBIE the regenerator is 25.242865 MMBtu an hour. What can that figure not tell you?', '["How large a reboiler the loop implies at the duty per gallon it was given.", "What it costs to reach one lean loading rather than another.", "How much solution the loop moves, which is the gallons a minute beside it.", "Which amine the loop is running, which the duty per gallon carries with it."]'::jsonb, 1, 'It is 800.000000 Btu on every gallon of 525.893013 gpm. It does not know the reboiler temperature, the reflux or the stripping steam, so it is a size rather than a cost.'),
  ('gasprocessing', 'intermediate', 'module', 'm04-three-amines-and-what-separates-them', 1, 'What does the molecular weight column of the amine property set do in the circulation chain?', '["It turns moles of amine into pounds of amine.", "It turns pounds of amine into pounds of solution.", "It turns moles of acid gas into moles of amine.", "It turns pounds of solution into gallons of solution."]'::jsonb, 0, 'It is the one column that is chemistry and nothing else. The strength turns amine into solution, the swing turns acid gas into amine, and the solution density turns pounds into gallons.'),
  ('gasprocessing', 'intermediate', 'module', 'm04-three-amines-and-what-separates-them', 2, 'Which column of the property set is the only one derivable from something outside this package?', '["The typical strength.", "The customary rich limit.", "The molecular weight.", "The customary duty per gallon."]'::jsonb, 2, 'The strengths, the rich limits, the duties and the gravities are customary practice with no publication behind them in this repository. They are declared constants, and pinning them is all a check can do.'),
  ('gasprocessing', 'intermediate', 'module', 'm04-three-amines-and-what-separates-them', 3, 'What does the property set carry for MDEA?', '["105.140000, 28.000000 weight percent, a rich limit of 0.400000, 950.000000 Btu a gallon and a gravity of 1.020000.", "119.160000, 45.000000 weight percent, a rich limit of 0.500000, 800.000000 Btu a gallon and a gravity of 1.040000.", "61.080000, 18.000000 weight percent, a rich limit of 0.350000, 1100.000000 Btu a gallon and a gravity of 1.010000.", "119.160000, 45.000000 weight percent, a rich limit of 0.400000, 950.000000 Btu a gallon and a gravity of 1.040000."]'::jsonb, 1, 'Each row is a coherent set: an amine at its own strength, loaded to its own limit, regenerated at its own duty, in a solution of its own density. The DEA and MEA rows carry their own five figures, and a set that borrows a rich limit and a duty from a neighbouring row describes nothing real.'),
  ('gasprocessing', 'intermediate', 'module', 'm04-three-amines-and-what-separates-them', 4, 'A caller names MDEA and says nothing about strength. What does the engine use?', '["45.000000 weight percent, and it reports nothing back about the choice.", "The strength of the previous call, since the property set holds no default.", "It refuses, because the strength is an input with no default on any row.", "45.000000 weight percent, the row''s own typical figure, and it reports which it used."]'::jsonb, 3, 'Each figure in the table is a default rather than a fixed property. Type a strength and the engine uses that instead, and the answer says which strength was applied either way.'),
  ('gasprocessing', 'intermediate', 'module', 'm04-three-amines-and-what-separates-them', 5, 'Why can the three printed circulations not be used to isolate the effect of strength?', '["The circulations are printed at one strength, so the column carries no variation at all.", "Strength enters after the gallons are formed, so it cannot move a circulation.", "Each row is computed at its own strength and its own rich limit, so two properties move together.", "The strengths are declared rather than measured, so no comparison between them is meaningful."]'::jsonb, 2, 'A difference between two rows is the combined effect of a different strength and a different loading limit, and nothing in the printed answer separates them. Holding everything and moving one input is what the panel is for.'),
  ('gasprocessing', 'intermediate', 'module', 'm04-three-amines-and-what-separates-them', 6, 'Strength appears in both answers the sweetening package returns. How?', '["It sets the gallons, and the regenerator is priced per gallon, so one typed number lands in both.", "It sets the gallons, and it is then applied a second time to the duty per gallon before the hours are formed.", "It sets the duty directly, and the gallons follow from the duty once the duty per gallon is divided out.", "It sets the loading swing, which the gallons and the duty both read."]'::jsonb, 0, 'Strength is a dilution: it carries an amount of active chemical into a much larger amount of liquid. The duty follows the gallons through the same step rather than through a second application.'),
  ('gasprocessing', 'intermediate', 'module', 'm04-three-amines-and-what-separates-them', 7, 'What follows from the rich limit being offered as the default rich loading?', '["The out of the box answer carries the corrosion warning on every one of the three amines.", "The out of the box answer sits below the limit by the lean loading.", "The default rich loading is the same on all three rows of the table.", "The out of the box answer for any amine sits exactly on the customary limit."]'::jsonb, 3, 'A design taken straight from the defaults is already at the edge of customary practice, and moving in the only direction that adds margin costs circulation. No warning is raised at the limit itself.'),
  ('gasprocessing', 'intermediate', 'module', 'm04-three-amines-and-what-separates-them', 8, 'The MDEA corrosion warning is read from both sides. What do the two rows show?', '["0.500000000 answers with the warning and 0.500001000 refuses.", "0.500000000 answers with no note and 0.500001000 answers with the warning attached.", "0.500000000 refuses and 0.500001000 answers with no note.", "Both rows answer with no note, because the limit belongs to MEA."]'::jsonb, 1, 'The limit itself is accepted and a millionth past it is flagged, which is the right way round. A guard that refuses its own stated limit is as wrong as one that lets nonsense through.'),
  ('gasprocessing', 'intermediate', 'module', 'm04-three-amines-and-what-separates-them', 9, 'A rich loading of 0.550000 is run on MDEA. Which description of the answer is right?', '["A refusal comes back, naming the customary limit.", "A circulation comes back and the duty is withheld.", "A circulation and a duty come back with the note attached.", "A circulation and a duty come back and the note is raised once a session."]'::jsonb, 2, 'The row reports 452.267991 gpm and 21.708864 MMBtu an hour and carries the note on that answer. Running rich is a decision an operator may take deliberately, so the engine has no standing to refuse it.'),
  ('gasprocessing', 'intermediate', 'module', 'm04-three-amines-and-what-separates-them', 10, 'The three amine rows carry a column of MMBtu an hour per gpm, at 0.066000000, 0.057000000 and 0.048000000. What is that column?', '["The duty per gallon of the property set in other units.", "A fourth property of each amine, measured out of the engine.", "The ratio of each amine''s duty to MDEA''s duty on the same case.", "The regenerator duty each amine needs on one gallon of acid gas."]'::jsonb, 0, 'Divide each amine''s customary duty by the minutes in a day and multiply by the minutes in an hour, and the same number comes back. When a ratio of two outputs turns out to be an input you already had, the ratio carries no information.'),
  ('gasprocessing', 'intermediate', 'module', 'm04-three-amines-and-what-separates-them', 11, 'The sweetening package is asked for DIPA. What comes back?', '["A refusal naming DIPA and nothing else.", "The MDEA row, since it is the nearest tertiary amine.", "An answer with every amine property left null.", "A refusal naming DIPA and listing MEA, DEA and MDEA."]'::jsonb, 3, 'This is the one catalogue lookup in the module and it says it does not know. A reader gets the correction and the catalogue in one line, without going to the source.'),
  ('gasprocessing', 'intermediate', 'module', 'm04-three-amines-and-what-separates-them', 12, 'What would a lookup that fell back to a default amine have produced instead?', '["A refusal raised one step further down the chain, where the missing property is first read.", "A complete and plausible answer for a solvent nobody asked about.", "An answer with the amine name left null in it.", "The same answer as one of the three rows, since the properties of the three sit close together."]'::jsonb, 1, 'Nothing in the module lets a caller add a fourth row, so a solvent outside these three has to be worked by hand. That is a scope boundary rather than a defect, and the refusal is what makes it visible.'),
  ('gasprocessing', 'intermediate', 'module', 'm04-three-amines-and-what-separates-them', 13, 'The same duty is put through all three amines. Which pair of figures belongs to DEA?', '["994.638143 gpm and 65.646117 MMBtu an hour.", "502.519990 gpm and 24.120960 MMBtu an hour.", "934.163599 gpm and 53.247325 MMBtu an hour.", "934.163599 gpm and 65.646117 MMBtu an hour."]'::jsonb, 2, 'MEA moves 994.638143 gpm and MDEA moves 502.519990 gpm on the same duty. Pairing the DEA circulation with the MEA regenerator describes a row that does not exist.'),
  ('gasprocessing', 'intermediate', 'module', 'm04-three-amines-and-what-separates-them', 14, 'MEA over MDEA is 1.979300649 on circulation and 2.721538393 on duty. Why do the two ratios differ?', '["Circulation is set by the rich limit and the strength, and duty adds the duty per gallon.", "Circulation is a mole balance and duty is a mass balance, so the two carry different bases.", "The circulation ratio is taken on one case and the duty ratio across the whole property set.", "Duty is a ratio of two engine figures and circulation is a ratio of two declared ones."]'::jsonb, 0, 'The same ordering is reached by two routes, so the gaps between the amines are different sizes on each. Quote 1.979300649 to somebody sizing a pump and 2.721538393 to somebody sizing a reboiler.'),
  ('gasprocessing', 'intermediate', 'module', 'm04-three-amines-and-what-separates-them', 15, 'A learner leaves this module quoting the ranking of the three amines as the solvent decision. What have they read wrongly?', '["The table, because the three rankings it carries do not agree with each other.", "The engine, because everything a selection usually turns on sits outside these three rows.", "The ratios, because a ranking taken on circulation reverses when it is taken on duty.", "The duty column, because the ranking it gives is the reverse of the circulation ranking."]'::jsonb, 1, 'The module does not separate CO2 from H2S, has no input for degradation, reclaiming or foaming, and carries no rate-based absorber model. The three orderings do agree, and that is exactly what makes the ranking look like a decision.'),
  ('gasprocessing', 'intermediate', 'module', 'm05-the-vessel-the-gas-goes-up', 1, 'Which course owns the Souders-Brown equation, the K value and the settling velocity?', '["This course, since the contactor sizing call is where the allowed velocity and the diameter are both formed.", "Separation and Slug Catching, which teaches the six published K rows and the mist extractor that sets them.", "Flow Assurance, which owns the gas side of every vessel in the package.", "Nobody in the package, because the allowed velocity is a chart reading that this engine simply takes as an input."]'::jsonb, 1, 'What is new in this module is the duty rather than the equation. A contactor is a mass transfer column, and it is sized on the gas that has to rise through a descending liquid.'),
  ('gasprocessing', 'intermediate', 'module', 'm05-the-vessel-the-gas-goes-up', 2, 'What is a contactor doing that a knockout drum is not?', '["Draining a liquid that has already fallen out of the gas.", "Holding a slug of liquid until the gas above it is dry.", "Separating two liquids from each other by density.", "Passing gas up through a liquid running down against it."]'::jsonb, 3, 'The arithmetic of the width happens to be the same arithmetic. The reason for it is different, and so is the liquid it is measured against.'),
  ('gasprocessing', 'intermediate', 'module', 'm05-the-vessel-the-gas-goes-up', 3, 'What are the diameters of the two teaching columns?', '["3.192661 ft on OBIAFU and 4.208602 ft on UBIE.", "4.208602 ft on OBIAFU and 3.192661 ft on UBIE.", "3.192661 ft on both, since one call sizes them.", "4.515105 ft on OBIAFU and 2.764926 ft on UBIE."]'::jsonb, 0, 'OBIAFU is a glycol column at 950.000000 psia and 104.000000 degF and UBIE is an amine column at 985.000000 psia and 112.000000 degF. The last pair are two rows of the K value sweep on one stream.'),
  ('gasprocessing', 'intermediate', 'module', 'm05-the-vessel-the-gas-goes-up', 4, 'Where does the compressibility in this sizing come from?', '["It is an input with a customary default on the page, in exactly the way the K value beside it is offered.", "It is read from the amine or glycol property table, which carries it beside the solution density and the molecular weight.", "The engine computes it from the DAK correlation off Sutton pseudo-criticals built from the gas gravity.", "It is taken from the gas properties door of the package, which exports a single figure covering every gas."]'::jsonb, 2, 'A compressibility is computable from first principles once a correlation has been chosen, so it is computed. A caller may supply one and the engine will use it, and the answer says which happened.'),
  ('gasprocessing', 'intermediate', 'module', 'm05-the-vessel-the-gas-goes-up', 5, 'The sweep carries a row at 1400.000000 psia and 60.000000 degF and a row at 2000.000000 psia and 110.000000 degF. What separates them?', '["The pressure alone moves, which is why the compressibility falls.", "The pressure and the temperature move and the gravity is held.", "The gravity alone moves, and the compressibility follows it.", "The pressure, the temperature and the gravity all move between those two rows."]'::jsonb, 3, 'The first carries a gravity of 0.700000 and a compressibility of 0.738367833, the second a gravity of 0.750000 and 0.751811429. A sentence attributing either figure to the pressure alone is a sentence about a calculation nobody performed.'),
  ('gasprocessing', 'intermediate', 'module', 'm05-the-vessel-the-gas-goes-up', 6, 'What can zSource report on a sizing answer?', '["Either the DAK correlation at these conditions, or the Sutton pseudo-criticals.", "Either the DAK correlation at these conditions, or supplied by the caller.", "Only the DAK correlation at these conditions, since the module forms its own.", "The correlation name and the validity band it was evaluated inside."]'::jsonb, 1, 'The two branches are genuinely different claims. A supplied compressibility is somebody''s assertion; a computed one is a correlation''s answer at stated conditions, with that correlation''s validity band behind it.'),
  ('gasprocessing', 'intermediate', 'module', 'm05-the-vessel-the-gas-goes-up', 7, 'Moving the K value from 0.150000 to 0.400000 on one stream does what?', '["Takes the allowed velocity from 0.659228 to 1.757940 ft per s and the diameter from 2.764926 to 4.515105 ft.", "Takes the allowed velocity from 1.757940 to 0.659228 ft per s and the diameter from 4.515105 to 2.764926 ft.", "Takes the allowed velocity from 0.659228 to 1.757940 ft per s and the diameter from 4.515105 to 2.764926 ft.", "Takes the allowed velocity from 0.659228 to 1.318455 ft per s and the diameter from 4.515105 to 3.192661 ft."]'::jsonb, 2, 'A higher allowed velocity needs less area to pass the same gas. The pair at 1.318455 and 3.192661 is the K of 0.300000 row, which is where OBIAFU sits.'),
  ('gasprocessing', 'intermediate', 'module', 'm05-the-vessel-the-gas-goes-up', 8, 'Why is the K value sweep the one clean single-variable sweep in this module?', '["Only the K value moves down it, on one stream at one pressure and one temperature.", "Only the K value has a customary default, so the other inputs cannot be moved.", "The K value enters the velocity linearly, which no other input does.", "The compressibility is held fixed down the sweep, which the engine allows for K alone."]'::jsonb, 0, 'The compressibility sweep moves three inputs at once and the amine comparison moves a strength and a rich limit together. Here a reader can be certain nothing else moved with it.'),
  ('gasprocessing', 'intermediate', 'module', 'm05-the-vessel-the-gas-goes-up', 9, 'What is a K value encoding that this engine cannot see?', '["A gas gravity, a pressure and a temperature, which the answer reports back.", "A mist extractor, an operating philosophy and a tolerance for entrainment.", "A liquid density and a solvent choice, which the property table carries.", "A stage efficiency and a tray spacing, which set the height of the same vessel."]'::jsonb, 1, 'None of those is visible to an engine that has been handed a rate, a pressure and a gravity. It is a choice, so it stays a choice, and it is on the page rather than hidden in the arithmetic.'),
  ('gasprocessing', 'intermediate', 'module', 'm05-the-vessel-the-gas-goes-up', 10, 'Somebody compares the OBIAFU and UBIE diameters. What must they carry alongside?', '["The two stage counts, since the height and the width are tied.", "The two absorption factors, which the sizing call takes as an input.", "The two circulations, which set the liquid load the vessel sees.", "The two K values, 0.300000 and 0.250000."]'::jsonb, 3, 'A diameter is conditional on a K value in exactly the way a stage count is conditional on an absorption factor. Quote one without the other and the number cannot be checked or reproduced.'),
  ('gasprocessing', 'intermediate', 'module', 'm05-the-vessel-the-gas-goes-up', 11, 'What liquid density does the sizing use when a caller says nothing?', '["64.883034 lb per ft3, the MDEA solution density.", "63.011408 lb per ft3, the lightest of the three amine solutions.", "69.568831 lb per ft3, the module''s one glycol density.", "It has no default and refuses until one is given."]'::jsonb, 2, 'A sweetening caller who says nothing gets a glycol column. The amine densities are built from each amine''s solution gravity: MEA 63.011408, DEA 63.635283 and MDEA 64.883034 lb per ft3.'),
  ('gasprocessing', 'intermediate', 'module', 'm05-the-vessel-the-gas-goes-up', 12, 'On one duty a column sized against glycol comes out 3.828818705 ft and against MDEA solution 3.900134220 ft. What does that pair say?', '["A column sized against the wrong liquid is confidently the wrong width, by a factor of 1.018625984 here.", "The amine column is wider because an amine solution carries more acid gas per gallon.", "The two liquids may be used interchangeably, since the two widths agree to a hundredth.", "The glycol figure is the conservative one, so it is the safe default for either service."]'::jsonb, 0, 'Confidently is the important word. Nothing in the answer looks unusual, the arithmetic is correct throughout, and the result is a plausible diameter for a vessel measured against a fluid it will never contain.'),
  ('gasprocessing', 'intermediate', 'module', 'm05-the-vessel-the-gas-goes-up', 13, 'The contactor golden comes in two kinds. What is the difference?', '["Three cases size against glycol, and two size against an amine solution.", "Three cases check the diameter, and two check the allowed velocity only.", "Three cases pass a compressibility in, and two let the engine compute its own.", "Three cases are published and two are the engine''s own answers restated."]'::jsonb, 2, 'A case that hands the engine half the answer can only check the other half. The two computing cases are the branch the live studio always takes, because it never passes a compressibility in.'),
  ('gasprocessing', 'intermediate', 'module', 'm05-the-vessel-the-gas-goes-up', 14, 'Why does the golden carry a case that is an amine column sized against an amine solution?', '["Because a golden made entirely of glycol columns would pass whatever the amine route did.", "Because the amine density is the only one the engine builds rather than reads.", "Because the amine route uses a different equation from the glycol route.", "Because an amine column is the only case the live studio ever runs."]'::jsonb, 0, 'A case only checks the path it walks. Reading a golden for what it omits is a slower and more useful exercise than reading it for what it agrees on.'),
  ('gasprocessing', 'intermediate', 'module', 'm05-the-vessel-the-gas-goes-up', 15, 'The sizing takes a gas rate, a pressure, a temperature, a gas gravity, a K value and a liquid density. Which of those is the design choice?', '["The liquid density.", "The K value.", "The gas gravity.", "The gas rate."]'::jsonb, 1, 'The liquid density describes the solvent the column is sized against and the other four describe the gas. A stage count and a diameter stay independent here, because the module carries no tray hydraulics to tie them together.'),
  ('gasprocessing', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'One sour column is read three ways in this tier. Which three?', '["A mole balance, a mass balance and a vessel.", "A stage relation, a tray hydraulic check and a vessel.", "A mole balance, a stage relation and a vessel.", "A mole balance, a stage relation and a regenerator heat balance."]'::jsonb, 2, 'Not one of the three can be derived from the other two. The regenerator duty is part of the mole balance answer rather than a fourth reading, since it is the circulation priced per gallon.'),
  ('gasprocessing', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Read as a mole balance, what does UBIE need?', '["525.893013 gpm of solution, on a regenerator of 25.242865 MMBtu an hour.", "10666.2009 gpm of solution, on a regenerator of 25.242865 MMBtu an hour.", "525.893013 gpm of solution, on a regenerator of 0.976783371 MMBtu an hour.", "502.519990 gpm of solution, on a regenerator of 24.120960 MMBtu an hour."]'::jsonb, 0, 'The 10666.2009 is the lbmol a day the balance starts from and 0.976783371 is the removal the same column reaches as a staged device. The last pair belongs to a rich loading of 0.500000 rather than to UBIE.'),
  ('gasprocessing', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'Read as a staged device at an absorption factor of 1.600000, what does the same column give?', '["0.976783371 removed at 6.000000 stages, and 5.658211483 stages for a removal of 0.990000.", "0.990000 removed at 6.000000 stages, and 7.746472598 stages for a removal of 0.976783371.", "0.922576074 removed at 6.000000 stages, and 3.140202390 stages for a removal of 0.990000.", "0.976783371 removed at 6.000000 stages, and 7.746472598 stages for a removal of 0.990000."]'::jsonb, 3, 'The 5.658211483 belongs to an absorption factor of 2.000000 at the same spec, 0.922576074 to a factor of 1.2 at six stages, and 3.140202390 to a removal of 0.900000 at 1.600000.'),
  ('gasprocessing', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'Read as a vessel, what does the same column come to?', '["4.208602 ft across, on a gas weighing 3.424553 lb per ft3 that may not rise faster than 1.318455 ft per s.", "4.208602 ft across, on a gas weighing 3.831017 lb per ft3 that may not rise faster than 1.035597 ft per s.", "3.192661 ft across, on a gas weighing 3.831017 lb per ft3 that may not rise faster than 1.035597 ft per s.", "4.208602 ft across, on a solution weighing 64.883034 lb per ft3 that may not rise faster than 1.035597 ft per s."]'::jsonb, 1, 'The gas is at 985.000000 psia and 112.000000 degF. The 3.424553 and 1.318455 belong to OBIAFU, and 64.883034 lb per ft3 is an MDEA solution density rather than a gas density.'),
  ('gasprocessing', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Which of the three readings makes no use of the gas rate at all?', '["The stage relation, because a removal is a fraction of whatever arrives.", "The vessel, because a diameter is set by the velocity and the density.", "The mole balance, because a mole percent is an intensive property.", "None of them, because all three are extensive answers about one column."]'::jsonb, 0, 'The mole balance turns on the rate at the step that makes lbmol a day, and the vessel is sized on the gas that has to pass through it. Only the stage relation does not know a rate exists.'),
  ('gasprocessing', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'A spec no real column could meet is handed to the mole balance. What happens?', '["It refuses, naming the removal the spec implies.", "It returns a circulation and attaches the ceiling as a warning.", "It returns a circulation for it without hesitating.", "It returns a circulation and the stage count the spec would need."]'::jsonb, 2, 'Reaching the spec is not the question the mole balance was asked. Whether the spec is reachable is the stage relation''s answer, and the two calls do not consult each other.'),
  ('gasprocessing', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'What can a stage count not do?', '["Say whether a spec is reachable.", "Size a pump.", "Compare two designs against one spec.", "Say which dial is binding on a column."]'::jsonb, 1, 'The stage relation says whether the spec is reachable and how much separation difficulty it represents. It says nothing about how many gallons a minute it takes to get there.'),
  ('gasprocessing', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'Which chosen inputs sit behind the vessel answer?', '["The absorption factor and the stage count.", "The swing, the strength and the duty per gallon.", "The gas gravity and the compressibility.", "The K value and the liquid density."]'::jsonb, 3, 'The swing, the strength and the duty per gallon sit behind the mole balance, and the absorption factor sits behind the staged reading. The gravity is a property of the stream and the compressibility is computed from it.'),
  ('gasprocessing', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'In what unit does this tier write a loading?', '["Moles of acid gas on each mole of amine.", "Weight percent of the circulating solution.", "Pounds of acid gas a gallon.", "A fraction of the acid gas arriving."]'::jsonb, 0, 'A weight percent is the strength of the solution, a fraction between zero and one is a removal, and the acid gas picked up is counted in lbmol a day. Four quantities, four units, and none of them substitutes for another.'),
  ('gasprocessing', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'Why can a removal and a mole percent never substitute for one another?', '["A removal is measured on the solution and a mole percent on the gas.", "A removal is a fraction between zero and one and a mole percent is a percentage.", "A removal is an engine answer and a mole percent is always a typed input.", "A removal carries the gas rate and a mole percent does not."]'::jsonb, 1, 'Both are typed inputs somewhere in this tier and both describe the gas side. What separates them is the unit, and a figure written in the wrong one answers a different question.'),
  ('gasprocessing', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Why does this tier ask for figures at the precision the engine prints?', '["A rounded figure falls outside the tolerance every graded field carries.", "The engine refuses any figure that carries fewer decimals than it printed.", "A rounded restatement of an engine answer cannot be told apart from an invented number.", "Rounding changes the unit, and the unit is what the marking reads."]'::jsonb, 2, 'Rounding on the way to an answer also carries the error forward into every step after it. Quote what the engine returned and round at the end, if at all.'),
  ('gasprocessing', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'A removal of 0.976783371 is quoted with nothing beside it. What is missing?', '["The gas rate and the pressure the column was run at, which every figure in this tier depends on.", "The swing and the strength the solution was carrying.", "The K value and the liquid density of the same vessel.", "The absorption factor of 1.600000 and the stage count of 6.000000 it belongs to."]'::jsonb, 3, 'The same relation at another factor gives a different figure that is equally correct and was not what was asked. Every circulation, duty and diameter in this tier is conditional in the same way, and on a different set of chosen numbers.'),
  ('gasprocessing', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'A question states an amine strength that differs from the property table''s own. Which figure is used?', '["The table one, since it is the amine''s typical value.", "The stated one, and the table figure is a distractor.", "Whichever of the two is nearer the customary band.", "Both, because the answer reports the strength it used."]'::jsonb, 1, 'The property table''s strengths, rich limits and duties are defaults, and a question is free to state its own. A figure produced from a different set of conditions is simply a different train.'),
  ('gasprocessing', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'The engine declines a spec set above the inlet. What is the right answer to write?', '["The circulation the inlet alone implies.", "A zero circulation, since nothing has to be removed.", "That it declines, and why.", "The nearest spec the engine would have accepted."]'::jsonb, 2, 'When the engine declines, the decline is the answer. A lean loading at or above the rich is refused by name, and a removal a starved absorber cannot reach is refused with the ceiling and the remedy attached.'),
  ('gasprocessing', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'Which module in this package computes a Joule-Thomson coefficient?', '["This one, and the Flow Assurance engine asks a caller to type one in.", "Flow Assurance, and this module takes one as a typed input.", "Both, and the two are checked against each other at the seam.", "Neither, because the coefficient is a chart value in this package."]'::jsonb, 0, 'That is why the tier above this one is where a learner finds out what number to type into the other app. Flow Assurance owns the coefficient as a subject and owns hydrates outright, and nothing in this engine computes a hydrate boundary.'),
  ('gasprocessing', 'intermediate', 'final', null, 1, 'What does a theoretical stage claim about the hardware it stands for?', '["That the gas and the liquid were in contact for a stated time on it.", "That one tray does the work of one stage at the service''s efficiency.", "Nothing at all, since only the equilibrium leaving it is specified.", "That the tray spacing is whatever the allowed velocity implies."]'::jsonb, 2, 'Equilibrium leaving the stage is the only thing asserted. Everything mechanical about the vessel is left to whoever turns a count into steel.'),
  ('gasprocessing', 'intermediate', 'final', null, 2, 'Hand the Kremser relation an absorption factor and a stage count. What comes back?', '["The fraction of the solute the column removes.", "The circulation the column needs, in gpm.", "The diameter the column needs, in ft.", "The lbmol a day the solvent picks up."]'::jsonb, 0, 'The relation is closed in all three of its variables, so the same expression rates a column that exists and sizes one that does not. A circulation and a diameter are separate calls.'),
  ('gasprocessing', 'intermediate', 'final', null, 3, 'In A = L / (V K), what is K?', '["The Souders-Brown K value of the vessel, in ft per s.", "The ratio of the rich loading to the lean loading on the solvent.", "The fraction of the solute the column is asked to remove.", "The equilibrium ratio of the solute between the two phases at the column''s conditions."]'::jsonb, 3, 'L is the solvent molar rate down the column and V is the gas molar rate up it. The factor is dimensionless and K is where the equilibrium sits.'),
  ('gasprocessing', 'intermediate', 'final', null, 4, 'Why does this module take the absorption factor as a typed input?', '["The factor changes between the top and the bottom of a real column.", "None of L, V or K is an argument of any export in it.", "The factor is a chart reading.", "The factor is returned by the sweetening call for the same stream."]'::jsonb, 1, 'Equilibrium data comes from outside this engine. What it answers is what a stated factor buys, and where that factor came from belongs to whoever typed it.'),
  ('gasprocessing', 'intermediate', 'final', null, 5, 'A column runs at an absorption factor of 1.600000 with 6.000000 stages, and the relation returns 0.976783371. What is that a fraction of?', '["The gas arriving at the column, in MMscfd.", "The solvent circulating round the loop.", "The solute arriving in the gas.", "The acid gas the spec allows to stay."]'::jsonb, 2, 'A fraction carries no unit and no rate. Two columns removing the same fraction of very different gas rates return the very same figure.'),
  ('gasprocessing', 'intermediate', 'final', null, 6, 'At an absorption factor of 1.000000 a spec of 0.900000 comes back as 9.000000000 stages. Which form produced it?', '["N = f / (1 - f), the branch the inverse takes at unity.", "N = log( (A - f) / (1 - f) ) / log(A) - 1, evaluated at A = 1.000000.", "N = A / (A - f).", "N = (1 - f) / f, the reciprocal of the branch."]'::jsonb, 0, 'The general form is indeterminate at unity in both directions, so the inverse has to match the forward branch rather than the general form, and the golden carries a case there for that reason.'),
  ('gasprocessing', 'intermediate', 'final', null, 7, 'One stage at an absorption factor of 0.6 removes how much?', '["0.444444444.", "0.375000000.", "0.500000000.", "0.600000000."]'::jsonb, 1, '0.444444444 is one stage at 0.8 and 0.500000000 is one stage at 1. The factor itself, 0.600000000, is the ceiling that column approaches over 200 stages rather than what one stage reaches.'),
  ('gasprocessing', 'intermediate', 'final', null, 8, 'A spec of 0.990000 is asked of a column at an absorption factor of 2.000000. What stage count comes back?', '["7.746472598.", "3.140202390.", "5.025685103.", "5.658211483."]'::jsonb, 3, '7.746472598 is the same spec at 1.600000, and the other two are a removal of 0.900000 at 1.600000 and at 1.200000. A better supplied column needs fewer stages for one spec.'),
  ('gasprocessing', 'intermediate', 'final', null, 9, 'Two hundred stages at an absorption factor of 0.800000 reach what removal?', '["0.768995039.", "0.788365257.", "0.800000000.", "0.888888889."]'::jsonb, 2, '0.768995039 is eight stages and 0.788365257 is twelve on that column. The ceiling is the factor, and 200 stages land on it to the last place printed.'),
  ('gasprocessing', 'intermediate', 'final', null, 10, 'A column at an absorption factor of 1.200000000000 carries 12 stages. What would 200 stages take the removal to?', '["1.000000000, because above unity there is no ceiling short of total removal.", "1.200000000, which is the factor and therefore the ceiling on that row.", "0.995024876, which is where 200 stages land on every row near unity.", "0.979379999, since the removal stops moving once the stages pass twelve."]'::jsonb, 0, 'The removal at 12 stages on that row is 0.979379999. The 0.995024876 belongs to the rows at and either side of unity, and a factor above one is not a ceiling at all.'),
  ('gasprocessing', 'intermediate', 'final', null, 11, 'What does the refusal on an unreachable removal hand back besides its message?', '["The absorption factor, the stage count tried and the ceiling.", "The absorption factor, the fraction removed and the ceiling.", "The ceiling, the spec and the circulation that would reach it.", "The message alone, since a refusal carries no fields."]'::jsonb, 1, 'Three fields beside the message, and between them they let a caller say what to change rather than only that something failed.'),
  ('gasprocessing', 'intermediate', 'final', null, 12, 'At an absorption factor of 0.950000000000, how far do 200 stages fall short of the ceiling?', '["0.000000000000.", "-0.004975123378.", "-0.000001665057.", "-0.000001665057 at 12 stages and nothing at 200."]'::jsonb, 2, 'The factors well below unity print exactly 0.000000000000 there, because the factor raised to the stage count falls below anything double precision holds. Only close to unity is the shortfall measurable at all.'),
  ('gasprocessing', 'intermediate', 'final', null, 13, 'The Kremser golden runs an absorption factor of 1.400000 over 6 stages. What do the engine and the cascade both return?', '["0.933333333333.", "0.833333333333.", "0.768995038974.", "0.958077213054."]'::jsonb, 3, 'Those three are the other published cases: a factor of 2.000000 over 3 stages, one of 1.000000 over 5, and one of 0.800000 over 8. All five ratios of engine over golden come back at 1.000000000000.'),
  ('gasprocessing', 'intermediate', 'final', null, 14, 'A vendor turns a theoretical count into real trays. What decides how much taller the real column comes out?', '["The tray efficiency of the service.", "The absorption factor the count was worked at.", "The removal the contract asked for.", "The allowed velocity the vessel was sized on."]'::jsonb, 0, 'It is a property of the service rather than of the arithmetic, and this package does not carry it. The count is still the right number for comparing two designs and for asking whether a spec is reachable.'),
  ('gasprocessing', 'intermediate', 'final', null, 15, 'What is 10666.2009 on the UBIE stream?', '["The acid gas going into the solution, in lb a day.", "The acid gas going into the solution, in lbmol a day.", "The amine going round the loop, in lbmol a day.", "The solution going round the loop, in gallons a day."]'::jsonb, 1, 'It is the mole percent removed applied to 88.000000 MMscfd through the standard cubic feet in a pound mole. The amine a day follows from it only after the swing has been divided out.'),
  ('gasprocessing', 'intermediate', 'final', null, 16, 'Which figure divides the acid gas rate on the way to a circulation?', '["The rich loading.", "The lean loading.", "The loading swing.", "The solution gravity."]'::jsonb, 2, 'Each mole of amine carries the swing round the loop, so the swing is what sets how many moles of amine there have to be. Either loading on its own sets nothing.'),
  ('gasprocessing', 'intermediate', 'final', null, 17, 'A sweetening answer echoes back the rich loading it applied. Why does it need to?', '["Because the rich loading is the one end of the loop a caller cannot type.", "Because the corrosion warning names the rich loading it was handed rather than the limit.", "Because the swing comes back on the same key once the lean loading is subtracted.", "Because the rich loading defaults to the customary limit of the amine that was named."]'::jsonb, 3, 'Every figure below it in the chain stands on that value. What comes back under no name at all is the swing, and forming the difference between the two ends is the reader''s own step.'),
  ('gasprocessing', 'intermediate', 'final', null, 18, 'Two spec refusals look alike. What separates a spec already met at the inlet from a spec set above it?', '["The first says the gas is on spec and the second says a figure larger than the inlet was typed beside it.", "The first is a warning and the second is a refusal.", "The first names both gases and the second names only the one at fault.", "The first is raised on the loadings and the second on the mole percentages."]'::jsonb, 0, 'Both messages quote both sides so the comparison can be made at a glance. The third refusal in that family is about the solvent loop rather than the gas, and it is the one that names the swing.'),
  ('gasprocessing', 'intermediate', 'final', null, 19, 'Down the lean loading table the MMBtu an hour per gpm column holds at 0.048000000. Why?', '["The regenerator duty is independent of the circulation in this model.", "The duty per gallon is a stated input the engine never changes.", "The lean loading enters the duty and the circulation in the same place.", "The swing cancels out of the ratio of the two engine figures."]'::jsonb, 1, '800.000000 Btu on every gallon circulated means the regenerator duty is the circulation in other units, so a leaner lean costs nothing here. On a real still it is bought with reboiler duty, stripping steam and a taller column.'),
  ('gasprocessing', 'intermediate', 'final', null, 20, 'Which step of the gallons chain is chemistry rather than practice or process?', '["The strength of the solution as it circulates.", "The customary rich limit of the amine.", "The molecular weight of the amine.", "The duty per gallon circulated."]'::jsonb, 2, 'A molecular weight is fixed by the molecule and can be checked in any handbook. Everything else in that chain was chosen by somebody, either as a design value or as the way a plant is run.'),
  ('gasprocessing', 'intermediate', 'final', null, 21, 'The plant is turned down. Which pair moves together?', '["The mole percent removed and the lbmol a day.", "The mole percent removed and the gpm.", "The swing and the lbmol a day.", "The lbmol a day and the gpm."]'::jsonb, 3, 'A mole percent and a swing are intensive and know nothing about how much gas there is. Everything extensive below them moves with the rate, the duty included.'),
  ('gasprocessing', 'intermediate', 'final', null, 22, 'Which column of the property set makes an MEA gallon dearer to regenerate than an MDEA one?', '["The duty, 1100.000000 against 800.000000 Btu a gallon.", "The typical strength, 18.000000 against 45.000000 weight percent.", "The rich limit, 0.350000 against 0.500000.", "The molecular weight, 61.080000 against 119.160000."]'::jsonb, 0, 'The other three decide how many gallons there are rather than what a gallon costs to strip. Both effects run the same way here, which is why the duty gap between the two amines is wider than the circulation gap.'),
  ('gasprocessing', 'intermediate', 'final', null, 23, 'One duty put through all three amines gives 994.638143 gpm on one of them. Which?', '["DEA.", "MEA.", "MDEA.", "All three, since the gallons follow the duty."]'::jsonb, 1, 'DEA moves 934.163599 gpm and MDEA 502.519990 gpm on the same duty. The gallons follow the rich limit and the strength, which differ on every row.'),
  ('gasprocessing', 'intermediate', 'final', null, 24, 'A loading of 0.500001000 is asked of MDEA. What comes back?', '["An answer with no note on it.", "A refusal naming the customary limit.", "An answer carrying a corrosion warning.", "An answer with the rich loading reset to 0.500000."]'::jsonb, 2, 'The limit itself is clean and a millionth past it is flagged. The message names the limit, names the amine it belongs to, and says what kind of trouble is being risked.'),
  ('gasprocessing', 'intermediate', 'final', null, 25, 'DEA over MDEA is 1.858958085 on one measure and 2.207512726 on another. Which is which?', '["1.858958085 is the duty ratio and 2.207512726 is the circulation ratio.", "1.858958085 is the strength ratio.", "1.858958085 is the gravity ratio.", "1.858958085 is the circulation ratio and 2.207512726 is the duty ratio."]'::jsonb, 3, 'Circulation is set by the rich limit and the strength; duty adds the duty per gallon, which is where the extra gap comes from. The same ordering is reached by two routes and the gaps are different sizes on each.'),
  ('gasprocessing', 'intermediate', 'final', null, 26, 'The module is asked for an amine it does not carry. What happens?', '["The lookup returns null and the package declines by name.", "The lookup returns the nearest row and the package answers on it.", "The lookup returns null and the default row answers.", "The lookup refuses and returns an empty set."]'::jsonb, 0, 'A lookup that falls back to a default produces a complete and plausible answer for a solvent nobody asked about. This one gives the correction and the catalogue in one line.'),
  ('gasprocessing', 'intermediate', 'final', null, 27, 'A rich limit from one row of the amine property set is used with a strength from another. What is wrong with that?', '["The engine refuses the pair, because it checks the strength and the limit against the amine named.", "The circulation comes back right and only the regenerator duty is wrong.", "Each row is one amine at its own strength and its own limit, so the pair describes nothing real.", "Nothing, because the strength and the rich limit enter the chain at different steps."]'::jsonb, 2, 'The engine will answer for any strength and any rich loading a caller types. What it cannot do is tell a reader that the pair describes no real plant, which is why the property set is read a row at a time.'),
  ('gasprocessing', 'intermediate', 'final', null, 28, 'All three ways of ranking the amines agree. What is the useful question left?', '["Which of the three rankings is the correct one to quote.", "How far apart the three are, which the two ratio columns answer differently.", "Whether the rankings would reverse at another duty.", "Which ranking the engine applies when it orders the property table."]'::jsonb, 1, 'A ranking stable across two measures is a real ranking. The size of the advantage is not stable, and quoting one ratio when the decision turns on the other is a mistake a single ordering hides completely.'),
  ('gasprocessing', 'intermediate', 'final', null, 29, 'At 950.000000 psia and 104.000000 degF on a gravity of 0.660000, what does the engine form?', '["A compressibility of 0.919606033 and a gas density of 2.045042 lb per ft3.", "A compressibility of 0.818461451 and a gas density of 5.672520 lb per ft3.", "A compressibility of 0.861800291 and a gas density of 3.831017 lb per ft3.", "A compressibility of 0.876617747 and a gas density of 3.424553 lb per ft3."]'::jsonb, 3, 'The first two of the others are rows at 600.000000 and 1400.000000 psia on different gravities, and the last is the UBIE column at 985.000000 psia and 112.000000 degF.'),
  ('gasprocessing', 'intermediate', 'final', null, 30, 'A K of 0.300000 on that same column gives what?', '["An allowed velocity of 1.098713 ft per s and a diameter of 3.497385 ft.", "An allowed velocity of 1.318455 ft per s and a diameter of 3.192661 ft.", "An allowed velocity of 1.538198 ft per s and a diameter of 2.955830 ft.", "An allowed velocity of 1.035597 ft per s and a diameter of 4.208602 ft."]'::jsonb, 1, 'The first two others are the K of 0.250000 and 0.350000 rows on the same stream. The last belongs to UBIE, which is a different stream sized at a different K.'),
  ('gasprocessing', 'intermediate', 'final', null, 31, 'What density does a DEA column rise against?', '["63.635283 lb per ft3.", "63.011408 lb per ft3.", "64.883034 lb per ft3.", "69.568831 lb per ft3."]'::jsonb, 0, 'Every row of the amine table carries a solution gravity and the module turns it into a density. A column sized on the default instead is measured against a fluid it will never contain.'),
  ('gasprocessing', 'intermediate', 'final', null, 32, 'What do the three published contactor cases that pass a compressibility in actually check?', '["The correlation, and never the sizing arithmetic.", "Both, since the compressibility is checked against the one supplied.", "The sizing arithmetic, and never the correlation.", "Neither, since a supplied compressibility makes the case a restatement."]'::jsonb, 2, 'A supplied compressibility takes the correlation out of the test entirely, so those cases speak only to the arithmetic that follows it. Two further cases exist for the other half.'),
  ('gasprocessing', 'intermediate', 'final', null, 33, 'A sizing answer comes back reporting zSource as supplied by the caller. What does that tell a reader?', '["The compressibility was formed by DAK at those conditions.", "The compressibility fell outside the correlation''s validity band.", "The compressibility was read from the amine property table.", "The compressibility is somebody''s assertion rather than a correlation''s answer."]'::jsonb, 3, 'A reader of the answer is never guessing which branch produced the number in front of them, and the two branches are genuinely different claims.'),
  ('gasprocessing', 'intermediate', 'final', null, 34, 'Two columns on one duty come out 3.828818705 ft and 3.900134220 ft. What is the 1.018625984 between them?', '["The factor between a column sized at two different K values.", "The factor between a column sized against glycol and one sized against MDEA solution.", "The factor between the engine and the golden on the amine case.", "The factor between a column at 950.000000 psia and one at 985.000000 psia."]'::jsonb, 1, 'A glycol density and an amine solution density are different numbers, and a column sized against the wrong one is confidently the wrong width.'),
  ('gasprocessing', 'intermediate', 'final', null, 35, 'This module gives a stage count and a diameter for one column. What ties them together?', '["The allowed velocity, which both readings share.", "The liquid density, which the stage relation also reads.", "Nothing here, because the module carries no tray hydraulics.", "The absorption factor, which sets the liquid load the vessel sees."]'::jsonb, 2, 'Tray hydraulics really do tie the two on a plant. The module does not pretend to a link it cannot compute, so a column can be six theoretical stages tall and any width the gas rate demands.'),
  ('gasprocessing', 'intermediate', 'final', null, 36, 'Three answers about one sour column. What is true of them?', '["Not one of them can be derived from the other two.", "Each is a check on the other two at the seam.", "Two are engine answers and the third is a chart reading.", "Each is computed from the same six inputs in a different order."]'::jsonb, 0, 'The mole balance says how much solution has to move, the stage relation says whether the spec is reachable, and the vessel says how wide the steel has to be. They arrive on one screen about one vessel and they are independent.'),
  ('gasprocessing', 'intermediate', 'final', null, 37, 'Which reading answers how much solution has to move?', '["The stage relation.", "The vessel sizing.", "The regenerator duty.", "The mole balance."]'::jsonb, 3, 'The regenerator duty is that same answer priced per gallon rather than a reading of its own. A stage count cannot size a pump and a diameter cannot either.'),
  ('gasprocessing', 'intermediate', 'final', null, 38, 'Every figure in the three Professional readings of one column stands on numbers somebody chose. Which of these is NOT one of those chosen numbers?', '["The lean loading the solution comes back from the regenerator on.", "The loading swing the circulation follows.", "The absorption factor the column is read at.", "The Souders-Brown K value the vessel is sized at."]'::jsonb, 1, 'The swing is the difference between two loadings a caller chose, so it is formed rather than typed. Write the rest down before reading any answer: the two loadings, the strength and the duty per gallon behind the mole balance, the absorption factor and the stage count behind the staged reading, and the K value and the liquid behind the vessel.'),
  ('gasprocessing', 'intermediate', 'final', null, 39, 'A graded question asks for a figure the engine declines to produce. What is the answer?', '["The nearest figure the engine would have returned.", "A zero, since the engine produced nothing.", "That it declines, with the reason it gives.", "The figure worked by hand from the same inputs."]'::jsonb, 2, 'Writing a plausible figure into that gap turns a correct reading into a wrong answer, and the gap was the point of the question. A refusal names what to change and by how much.'),
  ('gasprocessing', 'intermediate', 'final', null, 40, 'In what units are a circulation and a regenerator duty written in this tier?', '["A circulation is in gpm and a regenerator duty is in MMBtu an hour.", "A circulation is in gpm and a regenerator duty is in Btu a gallon.", "A circulation is in gallons a day and a duty is in MMBtu an hour.", "A circulation is in lbmol a day and a duty is in MMBtu an hour."]'::jsonb, 0, 'Btu a gallon is the duty per gallon that prices the loop rather than the regenerator size, gallons a day is the same circulation before the minutes in a day, and lbmol a day is the acid gas the solution picks up.'),
  ('gasprocessing', 'intermediate', 'final', null, 41, 'Why can a diameter quoted on its own not be reproduced?', '["It is conditional on a compressibility the engine may or may not have formed.", "It is conditional on the liquid the caller named, which the answer does not report.", "It is conditional on the stage count, which the sizing call is never given.", "It is conditional on a K value somebody chose, and that choice is not in the figure."]'::jsonb, 3, 'The answer does report both the liquid and where the compressibility came from. Every choice in this module is an input on the page with its customary value named, and a figure lifted away from those choices is a number without a question.'),
  ('gasprocessing', 'intermediate', 'final', null, 42, 'Which quantity does this engine compute that the Flow Assurance engine takes as a typed input?', '["The hydrate boundary.", "The Joule-Thomson coefficient.", "The compressibility of the gas.", "The Souders-Brown allowed velocity."]'::jsonb, 1, 'A caller of that engine has to bring the figure from somewhere, and this module is where it is formed from a correlation. Working the chain it feeds is the tier above this one.');
